// PC port: one-time unlock of the owned paid DLC (SaleType == 1).
// Generated by scripts/apply_dlc_unlock.py from the game's own Ac* tables.
// It reuses StoreManager's private ProductSet(type, id, true), so the
// bitfields and the CRC32+XOR share.bin format stay canonical.
public partial class StoreManager
{
    public void UnlockOwnedDlc()
    {
        bool changed = false;
        changed |= UnlockDlcItem(ProductType.BG2D, 3, IsBG2D(3));
        changed |= UnlockDlcItem(ProductType.BG2D, 4, IsBG2D(4));
        changed |= UnlockDlcItem(ProductType.BG2D, 5, IsBG2D(5));
        changed |= UnlockDlcItem(ProductType.BG2D, 6, IsBG2D(6));
        changed |= UnlockDlcItem(ProductType.BG2D, 7, IsBG2D(7));
        changed |= UnlockDlcItem(ProductType.BG2D, 10, IsBG2D(10));
        changed |= UnlockDlcItem(ProductType.BG2D, 11, IsBG2D(11));
        changed |= UnlockDlcItem(ProductType.BG2D, 12, IsBG2D(12));
        changed |= UnlockDlcItem(ProductType.BG2D, 13, IsBG2D(13));
        changed |= UnlockDlcItem(ProductType.BG2D, 14, IsBG2D(14));
        changed |= UnlockDlcItem(ProductType.BG2D, 15, IsBG2D(15));
        changed |= UnlockDlcItem(ProductType.BG2D, 16, IsBG2D(16));
        changed |= UnlockDlcItem(ProductType.BG2D, 17, IsBG2D(17));
        changed |= UnlockDlcItem(ProductType.BG2D, 18, IsBG2D(18));
        changed |= UnlockDlcItem(ProductType.BG3D, 2, IsBG3D(2));
        changed |= UnlockDlcItem(ProductType.BG3D, 3, IsBG3D(3));
        changed |= UnlockDlcItem(ProductType.BG3D, 4, IsBG3D(4));
        changed |= UnlockDlcItem(ProductType.BG3D, 5, IsBG3D(5));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 2, IsClothesKazusa(2));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 3, IsClothesKazusa(3));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 4, IsClothesKazusa(4));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 6, IsClothesKazusa(6));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 7, IsClothesKazusa(7));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 8, IsClothesKazusa(8));
        changed |= UnlockDlcItem(ProductType.ClothesKazusa, 5, IsClothesKazusa(5));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 2, IsClothesSetuna(2));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 3, IsClothesSetuna(3));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 4, IsClothesSetuna(4));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 6, IsClothesSetuna(6));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 7, IsClothesSetuna(7));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 8, IsClothesSetuna(8));
        changed |= UnlockDlcItem(ProductType.ClothesSetuna, 5, IsClothesSetuna(5));
        changed |= UnlockDlcItem(ProductType.FaceAccessoryKazusa, 1, IsFaceAccessoryKazusa(1));
        changed |= UnlockDlcItem(ProductType.FaceAccessorySetuna, 1, IsFaceAccessorySetuna(1));
        changed |= UnlockDlcItem(ProductType.HeadAccessoryKazusa, 1, IsHeadAccessoryKazusa(1));
        changed |= UnlockDlcItem(ProductType.HeadAccessoryKazusa, 2, IsHeadAccessoryKazusa(2));
        changed |= UnlockDlcItem(ProductType.HeadAccessoryKazusa, 3, IsHeadAccessoryKazusa(3));
        changed |= UnlockDlcItem(ProductType.HeadAccessorySetuna, 2, IsHeadAccessorySetuna(2));
        changed |= UnlockDlcItem(ProductType.HeadAccessorySetuna, 3, IsHeadAccessorySetuna(3));
        changed |= UnlockDlcItem(ProductType.HeadAccessorySetuna, 4, IsHeadAccessorySetuna(4));
        changed |= UnlockDlcItem(ProductType.HeadAccessorySetuna, 5, IsHeadAccessorySetuna(5));
        changed |= UnlockDlcItem(ProductType.HeadAccessorySetuna, 6, IsHeadAccessorySetuna(6));
        changed |= UnlockDlcItem(ProductType.Spt, 1, IsSpt(1));
        changed |= UnlockDlcItem(ProductType.PVKazusa, 1, IsPVKazusa(1));
        changed |= UnlockDlcItem(ProductType.PVKazusa, 2, IsPVKazusa(2));
        changed |= UnlockDlcItem(ProductType.PVKazusa, 3, IsPVKazusa(3));
        changed |= UnlockDlcItem(ProductType.PVKazusa, 4, IsPVKazusa(4));
        changed |= UnlockDlcItem(ProductType.PVKazusa, 5, IsPVKazusa(5));
        changed |= UnlockDlcItem(ProductType.PVSetuna, 1, IsPVSetuna(1));
        changed |= UnlockDlcItem(ProductType.PVSetuna, 2, IsPVSetuna(2));
        changed |= UnlockDlcItem(ProductType.PVSetuna, 3, IsPVSetuna(3));
        changed |= UnlockDlcItem(ProductType.PVSetuna, 4, IsPVSetuna(4));
        changed |= UnlockDlcItem(ProductType.PVSetuna, 5, IsPVSetuna(5));
        changed |= UnlockDlcItem(ProductType.PVEdit, 1, IsPVEdit(1));
        changed |= UnlockDlcItem(ProductType.PVEdit, 2, IsPVEdit(2));
        changed |= UnlockDlcItem(ProductType.PVEdit, 3, IsPVEdit(3));
        changed |= UnlockDlcItem(ProductType.PVEdit, 4, IsPVEdit(4));
        if (changed)
        {
            SD_Save();
        }
    }

    private bool UnlockDlcItem(ProductType type, int id, bool alreadyOwned)
    {
        if (alreadyOwned)
        {
            return false;
        }
        ProductSet(type, id, true);
        return true;
    }
}
